from tkinter import *
import calendar

screen=Tk()
screen.geometry("900x900")

def displaymonth():                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
    year=int(entb1.get())
    month=int(entmthb1.get())
    content=calendar.month(year,month)
    mth=Label(screen,text=content)
    mth.place(x=350,y=550)
    


cal1=Label(screen,text="Month Calendar",font=("Courier",25))
cal1.place(x=250,y=100)

entyr=Label(screen,text="Enter year")
entyr.place(x=280,y=400)

entb1=Entry(screen)
entb1.place(x=220,y=450)

entmonth=Label(screen,text="Enter month")
entmonth.place(x=480,y=400)

entmthb1=Entry(screen)
entmthb1.place(x=420,y=450)


butc1=Button(screen,text="Show month",command=displaymonth)
butc1.place(x=350,y=790)

mainloop()